#include "sio_uart_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static void sio_uart_rx_flush (Sio_Uart sio_uart) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

SInt16 sio_uart_ctrl_rx_flush_t (Sio_Uart sio_uart , Sio_Timeout timeout)
{
  //ATOMIC
  //  (
      sio_uart_irq_rx_dis (sio_uart) ;
        {
          MbxMsg * rx_data ;

          sio_uart_rx_flush (sio_uart) ;
      
          while ((rx_data = os_mbx_rcev_c (sio_uart->rx.q_rcev)) != 0)
            {
              os_mbx_send (sio_uart->rx.q_free , rx_data) ;
            }
      
          sio_uart_rx_flush (sio_uart) ;
        }
      sio_uart_irq_rx_ena (sio_uart) ;
  //  )

  return SIO_OK ;
}

//--------------------------------------------------------------------------//

static void sio_uart_rx_flush (Sio_Uart sio_uart)
{
  while (sio_uart->uart_reg [ULSR] & BIT_RDR)
    {
      sio_uart->uart_reg [URBR] ;  // Effect a 'read' and discard data
    }
}

